data.problem:
Возврат указателя на локальную переменную

char *greeting(void) {
    char buf[20];
    strcpy(buf, "Hi there");
    return buf;
}

int main(void) {
    char *g = greeting();
    printf("%s\n", g);
    return 0;
}

data.result:
Правильный код с использованием static:

char *greeting(void) {
    static char buf[20];
    strcpy(buf, "Hi there");
    return buf;
}

int main(void) {
    char *g = greeting();
    printf("%s\n", g);
    return 0;
}

data.problem:
Неинициализированный (дикий) указатель

int *p; // -> Memory address
*p = 10;
printf("%d\n", *p);

data.result:
Правильный код:

int v;
int *p = &v;
*p = 10;
printf("%d\n", *p);

data.problem:
Передача по значению

void swap(int a, int b) {
    int t = a;
    a = b;
    b = t;
}

int main(void) {
    int x = 1, y = 2;
    swap(x, y);
    printf("%d %d\n", x, y);
    return 0;
}

data.result:
Правильный код с указателями:

void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}

int main(void) {
    int x = 1, y = 2;
    swap(&x, &y);
    printf("%d %d\n", x, y);
    return 0;
}

data.problem:
malloc без +1 для '\0'

char *s = "hello";
char *copy = malloc(strlen(s));
strcpy(copy, s);
printf("%s\n", copy);
free(copy);

data.result:
Правильный код:

char *s = "hello";
char *copy = malloc(strlen(s) + 1);
strcpy(copy, s);
printf("%s\n", copy);
free(copy);

data.problem:
Беззнаковый счётчик в обратном цикле

char s[] = "abc";
for (size_t i = strlen(s) - 1; i >= 0; i--) {
    putchar(s[i]);
}
putchar('\n');

data.result:
Правильный код с использованием знакового типа:

char s[] = "abc";
for (int i = (int)strlen(s) - 1; i >= 0; i--) {
    putchar(s[i]);
}
putchar('\n');

/* или: */
char t[] = "abc";
for (size_t i = strlen(t); i > 0; i--) {
    putchar(t[i - 1]);
}
putchar('\n');

data.problem:
Пропущен & в scanf

int x;
scanf("%d", x);
printf("%d\n", x);

data.result:
Правильный код:

int x;
scanf("%d", &x);
printf("%d\n", x);
